def choose_move(observation):
    def _pos(v, default=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        return default

    def _num(v, default=0):
        return v if isinstance(v, int) else default

    def _sign(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def _dist(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def _best_target(targets, me, prefer_far=False):
        best = None
        best_score = None
        for t in targets or []:
            p = _pos(t)
            if p is None:
                continue
            s = _dist(me, p)
            if prefer_far:
                s = -s
            if best is None or s < best_score:
                best = p
                best_score = s
        return best

    env = observation.get("environment_name", "resource_collection")
    me = _pos(observation.get("self_position"), [0, 0])
    opp = _pos(observation.get("opponent_position"), me)

    gw = _num(observation.get("grid_width"), 0)
    gh = _num(observation.get("grid_height"), 0)
    center = [gw // 2 if gw else me[0], gh // 2 if gh else me[1]]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            target = opp
            if target is None:
                target = center
            return [_sign(me[0], target[0]), _sign(me[1], target[1])]
        corners = []
        if gw and gh:
            corners = [[0, 0], [0, gh - 1], [gw - 1, 0], [gw - 1, gh - 1]]
        else:
            corners = [[me[0] - 1, me[1] - 1], [me[0] - 1, me[1] + 1], [me[0] + 1, me[1] - 1], [me[0] + 1, me[1] + 1]]
        target = _best_target(corners, opp, prefer_far=True) or corners[0]
        return [_sign(me[0], target[0]), _sign(me[1], target[1])]

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("neutral_cells")
            or observation.get("frontier_cells")
            or []
        )
        target = _best_target(targets, me)
        if target is None:
            target = _best_target([opp, center], me) or me
        return [_sign(me[0], target[0]), _sign(me[1], target[1])]

    resources = observation.get("resources") or observation.get("resource_cells") or observation.get("resource_positions") or []
    target = _best_target(resources, me)
    if target is not None:
        return [_sign(me[0], target[0]), _sign(me[1], target[1])]

    # Denial / fallback: move toward opponent or map center, whichever is sensible.
    if opp is not None:
        target = opp
    else:
        target = center
    return [_sign(me[0], target[0]), _sign(me[1], target[1])]

